var m = tree.current_scene
var army_idx = -1
for i in range(m.army_options.size()):
	if str(m.army_options[i].id) == "recon_stomps":
		army_idx = i
var zone_idx = -1
for i in range(m.deployment_options.size()):
	if str(m.deployment_options[i].id) == "hammer_anvil":
		zone_idx = i
if army_idx < 0 or zone_idx < 0:
	return "missing army_idx=%d zone_idx=%d" % [army_idx, zone_idx]
m.player1_dropdown.selected = army_idx
m.plan_editor_zone_dropdown.selected = zone_idx
return "%s|%s" % [str(m.army_options[army_idx].id), m._plan_editor_zone_id()]

var path = "user://ai_plans/recon_stomps_hammer_anvil.json"
if FileAccess.file_exists(path):
	var dir = DirAccess.open("user://ai_plans")
	if dir != null:
		dir.remove(path.get_file())
return FileAccess.file_exists(path)

# Deterministic first-fit pack of every remaining Player 1 unit (same helper
# as pm4_plan_editor_session — the point here is the RECORDING, not the layout).
var phase = PhaseManager.get_current_phase_instance()
var PX = 40.0
var order = []
for uid in GameState.state.units.keys():
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) != 1 or int(u.get("status", 0)) != 0:
		continue
	var m0 = u.get("models", [])[0]
	var d = m0.get("base_dimensions", {})
	var xw = PX * (float(d.get("length", m0.get("base_mm", 32))) / 25.4)
	var yh = PX * (float(d.get("width", m0.get("base_mm", 32))) / 25.4)
	order.append({"id": uid, "area": xw * yh * u.get("models", []).size(), "xw": xw, "yh": yh})
order.sort_custom(func(a, b): return a.area > b.area)
var placed = 0
var failed = []
for entry in order:
	var uid = str(entry.id)
	var n = GameState.state.units[uid].get("models", []).size()
	var xw = float(entry.xw)
	var yh = float(entry.yh)
	var gap = 0.2 * PX
	var cols = n
	while cols > 1 and (cols - 1) * (xw + gap) > 7.5 * PX:
		cols -= 1
	var block_w = cols * (xw + gap)
	var block_h = int(ceil(float(n) / float(cols))) * (yh + gap)
	var done = false
	var gy = 0.6
	while gy * PX + block_h < 18.0 * PX and not done:
		var gx = 0.6
		while gx * PX + block_w < 44.0 * PX and not done:
			var positions = []
			for i in range(n):
				positions.append(Vector2(
					gx * PX + (i % cols) * (xw + gap) + xw / 2.0,
					gy * PX + (i / cols) * (yh + gap) + yh / 2.0))
			var act = {"type": "DEPLOY_UNIT", "unit_id": uid, "player": 1, "model_positions": positions}
			if phase.validate_action(act).get("valid", false):
				if phase.execute_action(act).get("success", false):
					placed += 1
					done = true
			gx += 1.0
		gy += 1.0
	if not done:
		failed.append(uid)
if not failed.is_empty():
	return "FAILED:" + str(failed)
return placed

var n = 0
for uid in GameState.state.units.keys():
	if int(GameState.state.units[uid].get("status", 0)) == 2:
		n += 1
return n

var PV = load("res://scripts/PlanValidator.gd")
var REC = load("res://scripts/PlanRecorder.gd")
var plan = PV.load_plan_file("user://ai_plans/recon_stomps_hammer_anvil.json")
var res = PV.validate_plan(plan, REC.own_army(GameState.state, 1))
if not res.get("valid", false):
	return "INVALID: " + str(res.get("errors", []))
return "valid"

var PV = load("res://scripts/PlanValidator.gd")
var plan = PV.load_plan_file("user://ai_plans/recon_stomps_hammer_anvil.json")
return plan.get("deployment", {}).get("placements", []).size()

var PV = load("res://scripts/PlanValidator.gd")
var plan = PV.load_plan_file("user://ai_plans/recon_stomps_hammer_anvil.json")
var dep = plan.get("deployment", {})
return dep.get("order", []).size() == dep.get("placements", []).size()

var PV = load("res://scripts/PlanValidator.gd")
var plan = PV.load_plan_file("user://ai_plans/recon_stomps_hammer_anvil.json")
return str(plan.get("description", ""))

var PV = load("res://scripts/PlanValidator.gd")
var path = tree.current_scene.get_node("PlanSaveDialog").last_result.get("path", "")
var plan = PV.load_plan_file(str(path))
var PPI = 40.0
var worst = 0.0
var checked = 0
for placement in plan.get("deployment", {}).get("placements", []):
	var uid = str(placement.get("unit", ""))
	var unit = GameState.state.units.get(uid, {})
	var models = unit.get("models", [])
	var recorded = placement.get("models_inches", [])
	if models.size() != recorded.size():
		return "MODEL COUNT MISMATCH on %s: %d live vs %d recorded" % [uid, models.size(), recorded.size()]
	for i in range(models.size()):
		var live = models[i].get("position", null)
		if live == null:
			return "live model %s[%d] has no position" % [uid, i]
		var live_in = (live if live is Vector2 else Vector2(live.x, live.y)) / PPI
		var rec_in = Vector2(float(recorded[i][0]), float(recorded[i][1]))
		var dist = live_in.distance_to(rec_in)
		if dist > worst:
			worst = dist
		checked += 1
return "%d models, worst %.4fin" % [checked, worst]

