var PV = load("res://scripts/PlanValidator.gd")
var AIDM = load("res://scripts/AIDecisionMaker.gd")
var path = tree.current_scene.get_node("PlanSaveDialog").last_result.get("path", "")
var plan = PV.load_plan_file(str(path))
var PPI = 40.0
var worst_overall = 0.0
var fallbacks = []
for player in [1, 2]:
	var snap = GameState.create_snapshot()
	var units = {}
	for uid in snap.units.keys():
		var u = snap.units[uid].duplicate(true)
		if int(u.get("owner", 0)) != 1:
			continue
		u["owner"] = player
		u["status"] = 0
		for m in u.get("models", []):
			m["position"] = null
		units[uid] = u
	snap["units"] = units
	snap["meta"]["active_player"] = player
	AIDM.clear_all_plans()
	AIDM.set_player_plan(player, plan)
	for placement in plan.deployment.placements:
		var uid = str(placement.unit)
		if not units.has(uid):
			continue
		var action = AIDM._decide_deployment(snap, [{"type": "DEPLOY_UNIT", "unit_id": uid}], player)
		if action.is_empty() or str(action.get("type", "")) != "DEPLOY_UNIT":
			fallbacks.append("P%d:%s" % [player, uid])
			continue
		var positions = action.get("model_positions", [])
		for i in range(placement.models_inches.size()):
			if i >= positions.size():
				fallbacks.append("P%d:%s:short" % [player, uid])
				break
			var got = positions[i] / PPI
			var want = Vector2(float(placement.models_inches[i][0]), float(placement.models_inches[i][1]))
			if player != 1:
				want = Vector2(44.0 - want.x, 60.0 - want.y)
			var dist = got.distance_to(want)
			if dist > worst_overall:
				worst_overall = dist
		var live_models = snap.units[uid].models
		for i in range(live_models.size()):
			if i < positions.size():
				live_models[i]["position"] = positions[i]
		snap.units[uid]["status"] = 2
AIDM.clear_all_plans()
if not fallbacks.is_empty():
	return "FELL BACK: " + str(fallbacks)
return worst_overall
